S = "Hakeem Force Academy"
QS = [
 (S, "Which symbol is commonly used to represent the common difference of an arithmetic sequence?", ["r", "d", "n", "a"], 1,
  "In an arithmetic sequence each term is found by adding a fixed number to the previous term. That fixed number is called the common difference and is written d.", "The nth term of an arithmetic sequence is a + (n - 1)d, where a is the first term.", [1948]),
 (S, "Which angel is responsible for rain and provision according to Islamic belief?", ["Hazrat Jibrael (AS)", "Hazrat Israfeel (AS)", "Hazrat Mikael (AS)", "Hazrat Azrael (AS)"], 2,
  "In Islamic tradition Hazrat Mikael (Michael) is the angel in charge of rain and provision.", "Hazrat Jibrael brings revelation, Hazrat Israfeel will blow the Trumpet and Hazrat Azrael takes souls.", [1402, 3614]),
 (S, "Which number is different from the rest: 5, 7, 9, 12?", ["5", "7", "12", "9"], 2,
  "5, 7 and 9 are odd numbers, while 12 is an even number.", "A number is even if it is divisible by 2.", [3880]),
 (S, "Which one is different from the rest: A4, B5, C5, D7?", ["A4", "B5", "C5", "D7"], 2,
  "A, B, C, D are the 1st, 2nd, 3rd and 4th letters. The number is the letter position plus 3 in A4, B5 and D7 (1+3, 2+3, 4+3), but C5 breaks it because 3+3 is 6.", "In letter-number odd-one-out questions, convert letters to their alphabet positions first.", [3770]),
 (S, "Which one is different from the rest: X5, Y6, Z9?", ["X5", "Y6", "Z9", "All are the same"], 2,
  "The numbers follow the letters in order: X is followed by 5 and Y by 6, so Z should be followed by 7. Z9 breaks the pattern.", "X, Y and Z are the 24th, 25th and 26th letters of the alphabet.", [3772]),
 (S, "Choose the word closest in meaning to 'restricted'.", ["Limited", "Free", "Unlimited", "Open"], 0,
  "Restricted means kept within limits or not allowed freely, so the closest word is limited.", "The antonym of restricted is unrestricted or free.", [977, 526]),
 (S, "On which Prophet was the Holy Quran revealed?", ["Hazrat Isa (AS)", "Hazrat Musa (AS)", "Hazrat Dawood (AS)", "Hazrat Muhammad (PBUH)"], 3,
  "The Holy Quran was revealed to Prophet Muhammad (PBUH) through the angel Jibrael over about 23 years.", "Prophet Muhammad (PBUH) is the last Prophet of Allah.", [2334]),
 (S, "Which was the last complete surah of the Holy Quran to be revealed?", ["Surah An-Nasr", "Surah Al-Fatiha", "Surah Al-Ikhlas", "Surah Al-Alaq"], 0,
  "According to the commonly given view (from Ibn Abbas), Surah An-Nasr was the last complete surah revealed to the Holy Prophet (PBUH).", "Sources differ on the very last verse revealed; some name a verse of Surah Al-Baqarah or Surah Al-Maidah.", [490, 3602]),
 (S, "The first revelation to the Holy Prophet (PBUH) was the first verses of which surah?", ["Surah Al-Muddaththir", "Surah Al-Fatiha", "Surah Al-Muzzammil", "Surah Al-Alaq"], 3,
  "The first five verses revealed in the Cave of Hira were from Surah Al-Alaq, beginning with the word Iqra (Read).", "The first revelation came in the month of Ramadan when the Prophet (PBUH) was about 40 years old.", [3324, 1181]),
 (S, "Which Article of the 1973 Constitution of Pakistan gives the right to free and compulsory education to children aged 5 to 16?", ["Article 25A", "Article 16", "Article 19", "Article 37"], 0,
  "Article 25A was added by the 18th Amendment in 2010. It makes free and compulsory education a fundamental right for children aged 5 to 16.", "Article 16 deals with freedom of assembly, not education.", [570]),
 (S, "How many rings are there in the Olympic symbol?", ["4", "6", "5", "7"], 2,
  "The Olympic symbol has five interlocking rings coloured blue, yellow, black, green and red.", "The rings represent the five inhabited continents joined together.", [1775]),
 (S, "Which river is called the lifeline of Pakistan?", ["River Ravi", "River Jhelum", "River Sutlej", "River Indus"], 3,
  "The Indus is the longest river of Pakistan and its water supports most of the farming of the country, so it is called the lifeline of Pakistan.", "The Indus rises near Lake Mansarovar in Tibet and falls into the Arabian Sea.", [322]),
 (S, "The Indus Waters Treaty of 1960 divided how many rivers between India and Pakistan?", ["3", "4", "5", "6"], 3,
  "The treaty covered six rivers: the three eastern rivers (Ravi, Beas, Sutlej) went to India and the three western rivers (Indus, Jhelum, Chenab) went to Pakistan.", "The treaty was brokered by the World Bank and signed in Karachi on 19 September 1960.", [4468]),
 (S, "In a room there are 18 girls and 6 boys. What percentage of the people in the room are boys?", ["33 percent", "20 percent", "30 percent", "25 percent"], 3,
  "Total people = 18 + 6 = 24. Percentage of boys = 6/24 x 100 = 25 percent.", "The percentage of girls in the room is 75 percent.", [406]),
 (S, "The square root of a prime number is always what kind of number?", ["Irrational", "Rational", "Whole number", "Integer"], 0,
  "A prime number is not a perfect square, so its square root cannot be written as a fraction of two integers. Hence it is irrational.", "For example, the square root of 7 is about 2.6458 and never ends or repeats.", [857]),
 (S, "In which year was the first Round Table Conference held in London?", ["1928", "1932", "1935", "1930"], 3,
  "The first Round Table Conference was held in London from November 1930 to January 1931.", "Three Round Table Conferences were held between 1930 and 1932.", [37, 219]),
 (S, "Gwadar Port is situated on the coast of which sea?", ["Arabian Sea", "Red Sea", "Black Sea", "Caspian Sea"], 0,
  "Gwadar is a deep sea port in Balochistan and lies on the Arabian Sea coast.", "Gwadar is the main port of the China-Pakistan Economic Corridor (CPEC).", [2432]),
]
